import os
BASE='/Users/diego/Desktop/bike_controller_light'
def patch_file(path, reps):
    full=os.path.join(BASE,path)
    with open(full,'r',encoding='utf-8') as f: src=f.read()
    for old,new in reps:
        if old not in src: print(f'  NOT FOUND in {path}: {old[:60]}')
        src=src.replace(old,new)
    with open(full,'w',encoding='utf-8') as f: f.write(src)
    print(f'  OK: {path}')

